mapper.select:
SELECT s.stock_id, s.material_code, s.material_name, s.specification, s.unit, s.batch_no, s.expiry_date, DATEDIFF(s.expiry_date, CURDATE()) as remain_days, s.quantity, s.warehouse_name, s.location_name, s.manufacturer, CASE WHEN DATEDIFF(s.expiry_date, CURDATE()) <= 0 THEN 4 WHEN DATEDIFF(s.expiry_date, CURDATE()) BETWEEN 1 AND 30 THEN 3 WHEN DATEDIFF(s.expiry_date, CURDATE()) BETWEEN 31 AND 60 THEN 2 ELSE 1 END as warning_level FROM spd_stock s WHERE s.del_flag = 0 AND s.expiry_date IS NOT NULL
AND s.material_name LIKE CONCAT('%', #{query.materialName}, '%')
AND s.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND s.warehouse_id = #{query.warehouseId}
AND CASE WHEN DATEDIFF(s.expiry_date, CURDATE()) <= 0 THEN 4 WHEN DATEDIFF(s.expiry_date, CURDATE()) BETWEEN 1 AND 30 THEN 3 WHEN DATEDIFF(s.expiry_date, CURDATE()) BETWEEN 31 AND 60 THEN 2 ELSE 1 END = #{query.warningLevel}
ORDER BY remain_days ASC, s.create_time DESC
